// Read-only witness extraction from the SAVED shared state + acceleration.
// No IC state construction, mass solve, coefficient update or new control.
#define GFS_SHARED_TRACE_FACTORY_LIBRARY
#include "test_shared_trace_factory_v1.cpp"
#include "material_shared_trace_rhs.h"
static st::Factory read_saved(const std::string&path,const curved::Packet&p){
    FILE*in=fopen(path.c_str(),"rb");need(in,"saved initial shared-state checkpoint");uint64_t h[8];need(fread(h,sizeof(h),1,in)==1&&h[0]==0x4746535452433031ULL&&h[1]==1&&h[2]==1&&h[4]==p.record.size()&&h[5]==sizeof(STTriangle)&&h[6]==sizeof(STCoefficient),"same saved factory state identity");
    st::Factory f;for(const auto&r:p.record)f.cell.push_back(r.cell);std::sort(f.cell.begin(),f.cell.end());f.cell.erase(std::unique(f.cell.begin(),f.cell.end()),f.cell.end());f.triangle.resize(h[4]);need(fread(f.triangle.data(),sizeof(STTriangle),f.triangle.size(),in)==f.triangle.size(),"saved basis cache and reference metadata");f.dof.resize(h[3]);f.coefficient.resize(h[3]);std::vector<bool>seen(h[3]);
    for(size_t j=0;j<h[3];j++){uint64_t id[4];STCoefficient value;need(fread(id,sizeof(id),1,in)==1&&fread(&value,sizeof(value),1,in)==1&&id[0]<h[3]&&!seen[id[0]],"single-owner saved coefficient table");need(id[3]==id[0]%4,"same four-rank coefficient ownership");seen[id[0]]=true;f.dof[id[0]]={id[0],id[1],int(id[2]),int(id[3])};f.coefficient[id[0]]=value;}
    need(fgetc(in)==EOF,"saved shared checkpoint complete");fclose(in);
    for(size_t s=0;s<f.triangle.size();s++){auto&t=f.triangle[s];need(t.n<=ST_MAX&&t.n>=15&&f.cell[t.cell]==p.record[s].cell,"original source and physical cell identity");for(int a=0;a<3;a++)for(int k=0;k<2;k++)need(t.vertex[a][k]==p.record[s].triangle.geometry.x[a][k],"same reference vertices");for(int a=0;a<t.n;a++)need(t.id[a]>=0&&size_t(t.id[a])<f.dof.size(),"canonical saved global index");}
    return f;
}
struct Witness {R chi=0,trace_a_error=0,trace_B_squared_error=0,gradient_error=0,accel_error=0;double X=0,Y=0,l[3]={};uint64_t source=0,cell=0;};
static std::vector<R> mass_audit(const st::Factory&f,const std::vector<STPoint>&points,const std::vector<std::array<R,2>>&accel,int rank,const std::string&dest){
    std::vector<R> raw(f.triangle.size()*ST_MAX*ST_MAX),direct(raw.size());auto rawtriangle=f.triangle;for(auto&t:rawtriangle){for(int k=0;k<2;k++){t.bubble_shift[k]=0;for(int j=0;j<2;j++)t.bubble_encode[k][j]=k==j?1:0;}}
    for(const auto&p:points){STJet N[ST_MAX],old[ST_MAX];const auto&t=f.triangle[p.triangle];need(st_shape(t,p,N)&&st_shape(rawtriangle[p.triangle],p,old),"saved basis raw/direct mass audit");R dm=R(p.weight)*p.rho;R*A=raw.data()+p.triangle*ST_MAX*ST_MAX,*B=direct.data()+p.triangle*ST_MAX*ST_MAX;for(int a=0;a<t.n;a++)for(int b=0;b<t.n;b++){A[a*ST_MAX+b]+=dm*old[a].v*old[b].v;B[a*ST_MAX+b]+=dm*N[a].v*N[b].v;}}
    MPI_Allreduce(MPI_IN_PLACE,raw.data(),raw.size(),MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,direct.data(),direct.size(),MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);
    if(rank==0){shared_trace_rhs::Mass legacy(f,raw);R difference=0,scale=0,action2=0,force2=0,kinetic[24][2]={},U[24]={};std::vector<std::array<R,2>>delta(f.dof.size()),force(f.dof.size());
        for(size_t s=0;s<f.triangle.size();s++){const auto&t=f.triangle[s];const R*A=legacy.local.data()+s*ST_MAX*ST_MAX,*B=direct.data()+s*ST_MAX*ST_MAX;for(int a=0;a<t.n;a++)for(int b=0;b<t.n;b++){R d=A[a*ST_MAX+b]-B[a*ST_MAX+b];difference=std::max(difference,fabsl(d));scale=std::max(scale,fabsl(B[a*ST_MAX+b]));for(int k=0;k<2;k++){delta[t.id[a]][k]+=d*accel[t.id[b]][k];force[t.id[a]][k]+=A[a*ST_MAX+b]*accel[t.id[b]][k];R v=R(f.coefficient[t.id[a]].v[k])*f.coefficient[t.id[b]].v[k];kinetic[t.cell][0]+=.5L*A[a*ST_MAX+b]*v;kinetic[t.cell][1]+=.5L*B[a*ST_MAX+b]*v;}}}
        // Use the saved FULL-cell U; never replace unowned contributions0.
        std::ifstream input(dest+"/../shared_trace_rhs_v1_mpi4/initial_curvature.csv");need(bool(input),"saved complete initial cell ledger");std::string line;std::getline(input,line);while(std::getline(input,line)){unsigned long long id;R mean,thermal;if(sscanf(line.c_str(),"%llu,%Lg,%Lg",&id,&mean,&thermal)==3){auto it=std::lower_bound(f.cell.begin(),f.cell.end(),id);need(it!=f.cell.end()&&*it==id,"saved cell U identity");U[it-f.cell.begin()]=thermal;}}
        R Kerror=0;for(int c=0;c<24;c++){need(U[c]>0,"saved positive full-cell U");Kerror=std::max(Kerror,fabsl(kinetic[c][0]-kinetic[c][1])/U[c]);}for(size_t i=0;i<delta.size();i++)for(int k=0;k<2;k++){action2+=delta[i][k]*delta[i][k];force2+=force[i][k]*force[i][k];}
        FILE*out=fopen((dest+"/mass_metric_audit.json").c_str(),"w");need(out,"independent direct normalized-basis mass audit");fprintf(out,"{\"scope\":\"saved state; raw-Gram affine transform versus direct SAME normalized basis integration, no solve or state change\",\"max_entry_difference\":%.21Lg,\"max_entry_scale\":%.21Lg,\"relative_max_entry_difference\":%.21Lg,\"represented_acceleration_action_relative_difference\":%.21Lg,\"max_cell_kinetic_difference_over_U\":%.21Lg}\n",difference,scale,difference/scale,sqrtl(action2/force2),Kerror);fclose(out);
    }return raw;
}
static void pressure_audit(const st::Factory&f,const std::vector<STPoint>&points,const std::vector<std::array<R,2>>&saved,const std::vector<R>&raw,const STPhysics&physics,int rank,int ranks,const std::string&dest){
    auto p=physics;p.gravity=0;std::vector<STOutput>output(points.size());
    #pragma omp parallel for schedule(static)
    for(size_t i=0;i<points.size();i++)output[i]=st_evaluate(f.triangle.data(),f.coefficient.data(),points[i],p);
    shared_trace_rhs::Boundary boundary;auto F=shared_trace_rhs::forces(f,points,output,p,rank,ranks,boundary);std::array<shared_trace_rhs::Vec,2>a={shared_trace_rhs::Vec(f.dof.size()),shared_trace_rhs::Vec(f.dof.size())};R relative=0;
    if(rank==0){shared_trace_rhs::Mass M(f,raw);R total=0,pressure=0;for(int d=0;d<2;d++){auto s=shared_trace_rhs::solve(M,F[d]);a[d]=std::move(s.x);shared_trace_rhs::Vec full(f.dof.size());for(size_t i=0;i<full.size();i++)full[i]=saved[i][d];auto force=M.apply(full);total+=shared_trace_rhs::dot(force,force);pressure+=shared_trace_rhs::dot(F[d],F[d]);}relative=sqrtl(pressure/total);FILE*out=fopen((dest+"/pressure_load_acceleration.csv").c_str(),"w");need(out,"read-only pressure load decomposition");fprintf(out,"global_id,pressure_ax,pressure_ay\n");for(size_t i=0;i<f.dof.size();i++)fprintf(out,"%zu,%.21Lg,%.21Lg\n",i,a[0][i],a[1][i]);fclose(out);}
    for(int d=0;d<2;d++)MPI_Bcast(a[d].data(),a[d].size(),MPI_LONG_DOUBLE,0,MPI_COMM_WORLD);
    R max_pressure=0,max_gravity=0,witness_pressure=0,witness_total=0;uint64_t witness_count=0;
    for(const auto&q:points){const auto&t=f.triangle[q.triangle];STJet N[ST_MAX];GfsMaterialPoint12 original;need(st_shape(t,q,N)&&st_point(t,f.coefficient.data(),N,&original),"saved load-decomposition basis");R trP=0,trTotal=0;for(int j=0;j<t.n;j++){int id=t.id[j];trP+=a[0][id]*N[j].x+a[1][id]*N[j].y;trTotal+=saved[id][0]*N[j].x+saved[id][1]*N[j].y;}R x=q.X,y=q.Y,z=x*x+y*y+R(p.eps)*p.eps,omega2=powl(z,-1.5L),trG=-2*omega2+3*(x*x+y*y)*omega2/z;max_pressure=std::max(max_pressure,R(p.gamma)*fabsl(trP)/omega2);max_gravity=std::max(max_gravity,R(p.gamma)*fabsl(trTotal-trP-trG)/omega2);if(q.triangle==5&&q.X==9.6094583644768861&&q.Y==-5.4375000144862247){witness_pressure=trP;witness_total=trTotal-trG;witness_count++;}}
    MPI_Allreduce(MPI_IN_PLACE,&max_pressure,1,MPI_LONG_DOUBLE,MPI_MAX,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,&max_gravity,1,MPI_LONG_DOUBLE,MPI_MAX,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,&witness_pressure,1,MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,&witness_total,1,MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,&witness_count,1,MPI_UINT64_T,MPI_SUM,MPI_COMM_WORLD);
    if(rank==0){need(witness_count==1,"one saved worst-point witness");FILE*out=fopen((dest+"/pressure_load_audit.json").c_str(),"w");need(out,"native pressure load witness");fprintf(out,"{\"scope\":\"linear decomposition of SAME initial native weak load on SAVED shared state; no state update, mesh/order/precision change or alternative physical trajectory\",\"pressure_only_weak_load_relative_to_full_load\":%.21Lg,\"pressure_only_acceleration_chi_max\":%.21Lg,\"gravity_remainder_chi_max\":%.21Lg,\"worst_point_pressure_div_acceleration\":%.21Lg,\"worst_point_full_div_acceleration_error\":%.21Lg,\"pressure_fraction_at_saved_worst_point\":%.21Lg}\n",relative,max_pressure,max_gravity,witness_pressure,witness_total,witness_pressure/witness_total);fclose(out);}
}
int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);int code=2;
    try{need(argc==4,"original geometry SAVED shared RHS run NEW witness output");auto packet=curved::read(argv[1]);std::string saved=argv[2],dest=argv[3];auto f=read_saved(saved+"/initial_state.bin",packet);std::vector<std::array<R,2>>accel(f.dof.size());std::ifstream input(saved+"/shared_acceleration.csv");std::string line;std::getline(input,line);std::vector<bool>seen(accel.size());while(std::getline(input,line)){unsigned long long id;int owner;R ax,ay;need(sscanf(line.c_str(),"%llu,%d,%Lg,%Lg",&id,&owner,&ax,&ay)==4&&id<accel.size()&&!seen[id]&&owner==f.dof[id].owner,"saved sparse acceleration global ownership");seen[id]=true;accel[id]={ax,ay};}for(bool flag:seen)need(flag,"complete saved acceleration");auto points=positive_points(packet,f,rank,ranks);std::vector<Witness> worst(f.triangle.size());uint64_t checked=0;R eps=packet.parameters[3],gamma=packet.parameters[1];
        for(const auto&q:points){const auto&t=f.triangle[q.triangle];STJet N[ST_MAX];GfsMaterialPoint12 p;need(st_shape(t,q,N)&&st_point(t,f.coefficient.data(),N,&p),"saved initial point evaluation");R a[2]={},Da[4]={};for(int j=0;j<t.n;j++)for(int d=0;d<2;d++){a[d]+=accel[t.id[j]][d]*N[j].v;Da[2*d]+=accel[t.id[j]][d]*N[j].x;Da[2*d+1]+=accel[t.id[j]][d]*N[j].y;}R x=q.X,y=q.Y,z=x*x+y*y+eps*eps,o=powl(z,-1.5L),v=powl(z,-.75L),g[2]={-x*o,-y*o},Dg[4]={-o+3*x*x*o/z,3*x*y*o/z,3*x*y*o/z,-o+3*y*y*o/z},B[4]={1.5L*x*y*v/z,-v+1.5L*y*y*v/z,v-1.5L*x*x*v/z,-1.5L*x*y*v/z};R trA=Da[0]+Da[3]-Dg[0]-Dg[3],trB=R(p.grad_v[0])*p.grad_v[0]+2*R(p.grad_v[1])*p.grad_v[2]+R(p.grad_v[3])*p.grad_v[3]-(B[0]*B[0]+2*B[1]*B[2]+B[3]*B[3]),chi=gamma*fabsl(trA-trB)/o;
            auto&w=worst[q.triangle];if(chi>w.chi){w.chi=chi;w.trace_a_error=trA;w.trace_B_squared_error=trB;w.X=q.X;w.Y=q.Y;for(int k=0;k<3;k++)w.l[k]=q.l[k];w.source=q.triangle;w.cell=f.cell[t.cell];w.accel_error=hypotl(a[0]-g[0],a[1]-g[1]);R error=0;for(int k=0;k<4;k++)error+=(Da[k]-Dg[k])*(Da[k]-Dg[k]);w.gradient_error=sqrtl(error);}checked++;
        }
        auto raw=mass_audit(f,points,accel,rank,dest);STPhysics physics={packet.parameters[1],packet.parameters[2],packet.parameters[3],1};pressure_audit(f,points,accel,raw,physics,rank,ranks,dest);
        std::vector<Witness>gathered(rank==0?worst.size()*ranks:0);MPI_Gather(worst.data(),worst.size()*sizeof(Witness),MPI_BYTE,gathered.data(),worst.size()*sizeof(Witness),MPI_BYTE,0,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,&checked,1,MPI_UINT64_T,MPI_SUM,MPI_COMM_WORLD);
        if(rank==0){for(size_t s=0;s<worst.size();s++)worst[s]=gathered[(s%ranks)*worst.size()+s];std::sort(worst.begin(),worst.end(),[](const Witness&a,const Witness&b){return a.chi>b.chi;});FILE*out=fopen((dest+"/curvature_witnesses.csv").c_str(),"w");need(out,"read-only saved-state witness ledger");fprintf(out,"source,cell,X,Y,chi,lambda0,lambda1,lambda2,acceleration_error,gradient_error,div_acceleration_error,velocity_gradient_square_error\n");for(const auto&w:worst)fprintf(out,"%llu,%llu,%.17g,%.17g,%.21Lg,%.17g,%.17g,%.17g,%.21Lg,%.21Lg,%.21Lg,%.21Lg\n",(unsigned long long)w.source,(unsigned long long)w.cell,w.X,w.Y,w.chi,w.l[0],w.l[1],w.l[2],w.accel_error,w.gradient_error,w.trace_a_error,w.trace_B_squared_error);fclose(out);
            auto&w=worst[0];need(fabsl(w.chi-.0030783190557429997L)<1e-15L,"saved state reproduces original curvature failure without re-solving");printf("{\"scope\":\"saved state and acceleration read-only witness; no mass/RHS solve, coefficient update or scan\",\"points_checked\":%llu,\"worst_source\":%llu,\"worst_cell\":%llu,\"X\":%.17g,\"Y\":%.17g,\"chi\":%.17Lg,\"div_acceleration_error\":%.17Lg,\"velocity_gradient_square_error\":%.17Lg,\"smallest_barycentric_coordinate\":%.17g,\"old_curvature_failure_reproduced\":true}\n",(unsigned long long)checked,(unsigned long long)w.source,(unsigned long long)w.cell,w.X,w.Y,w.chi,w.trace_a_error,w.trace_B_squared_error,*std::min_element(w.l,w.l+3));code=0;
        }MPI_Bcast(&code,1,MPI_INT,0,MPI_COMM_WORLD);
    }catch(const std::exception&e){fprintf(stderr,"rank%d FAIL %s\n",rank,e.what());MPI_Abort(MPI_COMM_WORLD,2);}MPI_Finalize();return code;
}
